-- Новый тип ноды say_phrase («Сказать фразу»): ученик произносит английскую фразу в микрофон, приложение мягко
-- сверяет её с эталоном (Web Speech API в телефоне; звук не записывается и на сервер не уходит). Типы нод в БД
-- ничем не ограничены (проверено grep по supabase/migrations и baseline: тип хранится как текст внутри
-- lessons.script), поэтому таблиц, колонок, политик и RPC не меняем. Миграция только добавляет правило для
-- легенды обменного JSON — что писать в phrase/keywords/threshold и что нужно пояснение перед нодой.
-- Идемпотентно: вставка только если такого правила ещё нет. Текст тот же, что в lessonRulesDefaults.js.
insert into public.lesson_rules (rule_text, sort_order, category)
select
  'say_phrase («Сказать фразу») — ученик ПРОИЗНОСИТ английскую фразу в микрофон, приложение мягко сверяет её с эталоном (порядок слов не важен, мелкие неточности прощаются, звук не записывается и не сохраняется). phrase — эталон: обычная разговорная фраза на 3–8 слов с целевым словом урока, без перевода внутри; translation — по желанию; keywords — 1–2 ключевых слова из phrase через запятую (они должны прозвучать обязательно); threshold — 70 по умолчанию (50–100). Перед КАЖДОЙ нодой say_phrase нужна короткая текстовая нода-пояснение — что сейчас сказать вслух и что без микрофона можно нажать «Получилось» или «Не могу говорить» (штрафа нет). Не ставь say_phrase первой нодой урока и две подряд. Триггеры: say_done (основной; им же идёт «Получилось») и необязательный say_skip («Не могу говорить»; если не соединён, урок идёт по say_done).',
  250,
  'principle'
where not exists (
  select 1 from public.lesson_rules
  where rule_text like 'say_phrase («Сказать фразу») — ученик ПРОИЗНОСИТ английскую фразу в микрофон%'
);
